from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.enums import TA_LEFT
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output/pdf';OUT.mkdir(parents=True,exist_ok=True)
pdfmetrics.registerFont(TTFont('Arial',r'C:\Windows\Fonts\arial.ttf'))
pdfmetrics.registerFont(TTFont('ArialBold',r'C:\Windows\Fonts\arialbd.ttf'))
pdfmetrics.registerFont(TTFont('Mono',r'C:\Windows\Fonts\consola.ttf'))
pdfmetrics.registerFontFamily('Arial',normal='Arial',bold='ArialBold',italic='Arial',boldItalic='ArialBold')
navy=colors.HexColor('#15344A');teal=colors.HexColor('#007F83');muted=colors.HexColor('#526574')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyTR',fontName='Arial',fontSize=10.5,leading=14,spaceAfter=8,textColor=navy))
styles.add(ParagraphStyle(name='TitleTR',fontName='ArialBold',fontSize=27,leading=32,textColor=navy,spaceAfter=18))
styles.add(ParagraphStyle(name='H2TR',fontName='ArialBold',fontSize=14,leading=18,textColor=teal,spaceBefore=12,spaceAfter=8))
styles.add(ParagraphStyle(name='SmallTR',fontName='Arial',fontSize=8.7,leading=12,textColor=muted,spaceAfter=7))
styles.add(ParagraphStyle(name='CodeTR',fontName='Mono',fontSize=8.1,leading=11,backColor=colors.HexColor('#EDF3F6'),borderPadding=10,spaceBefore=6,spaceAfter=14))
