story=[]
def p(t):story.append(Paragraph(t,styles['BodyTR']))
def small(t):story.append(Paragraph(t,styles['SmallTR']))
def h(t):story.append(Paragraph(t,styles['H2TR']))
def title(n,t):
 if story:story.append(PageBreak())
 small('FREERTOS BOOTCAMP  /  UYGULAMA REHBERİ  /  '+n)
 story.append(Paragraph(t,styles['TitleTR']))
def code(t):story.append(Preformatted(t,styles['CodeTR']))
def table(rows,widths):
 data=[[Paragraph(escape(c),styles['Cell']) for c in row] for row in rows]
 tb=Table(data,colWidths=widths,hAlign='LEFT')
 tb.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#DAEBEE')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#CCDADF'))]))
 story.append(tb);story.append(Spacer(1,10))

title('01','SEGGER SystemView\nile kendi kaydını al')
p('<b>Senin projen için pratik rehber</b><br/>STM32F407VG • FreeRTOS 10.3.1 • SystemView 4.10a<br/>V1 / V2-QWB • S0 ve S5 • 6 Ekim 2026')
h('Önce sorunun cevabı')
p('Evet. Mevcut düzende önce karttan kısa bir kayıt alıyorsun. Hazırladığımız betik bunu <b>recording.SVDat</b> dosyasına dönüştürüyor. Ardından dosyayı SystemView’da açıp inceliyorsun. Kayıt zaten bilgisayardaysa kart bağlı olmadan da inceleyebilirsin.')
table([['Adım','Bu projede olan işlem'],['1. Çalıştır','PowerShell betiği senaryoyu başlatır ve kayıt süresini karta gönderir.'],['2. Kaydet','Firmware, görev ve kesme olaylarını kartın RAM’indeki RTT tamponuna yazar.'],['3. Dosyaya çıkar','Süre dolunca izleme durur. ST-LINK / OpenOCD RAM’i okur; betik izleme verisini ayırır.'],['4. İncele','recording.SVDat dosyasını SystemView’da açarsın.']], [73,426])
p('<b>İki ayrı iş var:</b> firmware’e izleme desteği eklemek bir hazırlık işidir. Hazırlık tamamlandıktan sonra günlük kullanımın kayıt komutunu çalıştırmak, butona basmak ve dosyayı açmaktır.')
h('Rehberin yolu')
p('2 - Bağlantılar ve hazırlık<br/>3 - S0 / S5 kaydı alma<br/>4 - Kayıt dosyaları ve doğrulama<br/>5 - SystemView ekranını kullanma<br/>6 - Gecikmenin nedenini bulma<br/>7 - V1 / V2 derleme ve karta yükleme<br/>8 - Yeni projeye taşıma<br/>9 - Sorun giderme ve başvuru')
small('Bu rehber yerel projedeki betiklere göre hazırlanmıştır. Belgede verilen komutlar rehber hazırlanırken çalıştırılmadı; kartın yazılımı değiştirilmedi. Son bilinen yüklü sürüm V1’dir. Sonradan yükleme yaptıysan sürümü buna göre seç.')

title('02','Bağlantıları hazırla')
table([['Bağlantı','Görevi'],['ST-LINK USB kablosu','Kart üzerine yazılım yükler. Kayıt sırasında SWD üzerinden RAM okumasını sağlar.'],['USB-TTL adaptörü','COM portundan senaryo komutlarını ve uygulamanın ölçüm verisini taşır. SystemView izleme akışı bu UART üzerinden gelmez.'],['USER butonu','Deneyde fiziksel olay üretir. Mavi USER butonunu kullan; siyah RESET butonu koşuyu yeniden başlatır.']], [142,357])
h('1. Kablolar ve COM portu')
p('Önceki çalışan bağlantıyı koru: adaptör <b>RX → PA2</b>, adaptör <b>TX → PA3</b>, <b>GND → GND</b>. UART mantık seviyesi karta uygun 3,3 V olmalıdır. Güç bağlantısını değiştirmene gerek yok.')
p('Aygıt Yöneticisi’nde “Bağlantı Noktaları (COM ve LPT)” bölümünden adaptörün COM numarasına bak. Mevcut örnekler COM5 kullanıyor. Numara değişmişse komutta yalnızca <b>-Port COM5</b> kısmını değiştir.')
h('2. Aynı bağlantıyı kullanan programları kapat')
p('Seri terminali veya uygulamanın COM portunu açık tutan arayüzünü kapat. CubeIDE’da aktif debug oturumu ve başka bir ST-LINK bağlantısı bulunmasın. SystemView’da eski bir dosyanın açık kalması sorun değildir.')
h('3. PowerShell’i proje klasöründe aç')
code('cd D:\\freertos-bootcamp\\hafta-02')
p('Komutların tamamında başlangıç klasörü burasıdır. V1 betiği de ortak bilgisayar ortamını kullandığı için <b>projects/v2/interface/.venv</b> içindeki Python’u çalıştırır; bu, yanlış sürümün kaydedildiği anlamına gelmez.')
h('4. Sürümü eşleştir')
p('<b>Kart V1 ise capture-v1.ps1; kart V2-QWB ise capture-v2.ps1.</b> Kayıt betiğinin kullandığı ELF, karttaki yazılımla aynı derlemeye ait olmalıdır. ELF dosyasından RAM sembollerinin adresleri okunur. Yalnızca betik adını değiştirerek karttaki sürümü değiştirmiş olmazsın.')
small('Bu düzende harici J-Link kullanılmaz. F5 ile canlı kayıt başlatmak yerine aşağıdaki PowerShell akışı kullanılır. ST-LINK’in J-Link’e dönüştürülmesi gerekmez.')

title('03','S0 ve S5 kaydını al')
p('<b>S0:</b> telemetri yükü yok; buton yolunun temel gecikmesini gözlemlersin.<br/><b>S5:</b> 100 Hz telemetri yükü ve CPU işi etkin; görev beklemesi ve TX kuyruğunun etkisini gözlemlersin.')
h('V1 karta yüklüyken')
code('.\\tools\\capture-v1.ps1 -Scenario S0 -Windows 6 -WindowMs 1000 -Port COM5\n\n.\\tools\\capture-v1.ps1 -Scenario S5 -Windows 8 -WindowMs 500 -Port COM5')
h('V2-QWB karta yüklüyken')
code('.\\tools\\capture-v2.ps1 -Scenario S0 -Windows 6 -WindowMs 1000 -Port COM5\n\n.\\tools\\capture-v2.ps1 -Scenario S5 -Windows 8 -WindowMs 500 -Port COM5')
p('<b>Komutları tek tek çalıştır.</b> Önce S0 koşusu tamamen bitsin; sonra S5’i başlat. Betik senaryoyu seçer, koşuyu başlatır ve hazırlık için yaklaşık 6 saniye bekler.')
h('Komut çalışırken sen ne yapacaksın?')
p('1. Terminalde <b>CAPTURE 1/6: press USER now</b> benzeri yazıyı bekle.<br/>2. Mavi USER butonuna bas. Sonraki CAPTURE satırlarını takip ederek basışları tekrarla. Yaklaşık saniyede bir basışla başlayabilirsin.<br/>3. Her pencere sonunda <b>Saved ... bytes</b> ve dosya yolu görünür.<br/>4. Son pencereden sonra da bekle. Betik STOP ve ölçüm dökümünü tamamlar; V1’de son okuma yaklaşık 12 saniye sürebilir.<br/>5. <b>OUTPUT=...</b> görünmesi ve komut satırının geri gelmesiyle koşu biter.')
table([['Parametre','Anlamı'],['-Windows 8','Sekiz ayrı kayıt penceresi. İşletim sisteminin adıyla ilgili değil.'],['-WindowMs 500','Her pencere 500 ms. Dışa aktarma sırasında pencereler arasında boşluk vardır.'],['-Scenario S5','Firmware’de tanımlı S5 yükünü seçer.']], [142,357])
small('500 ms’lik pencereye her basış denk gelmeyebilir. BTN_ACCEPT içermeyen bir pencereyle buton gecikmesi çıkarma; başka pencereyi aç veya tekrar kayıt al. Uzun süre sınırsız basma: uygulamanın olay saklama kapasitesi sınırlıdır. Kayıt süresini büyütmek 64 KiB izleme tamponunu taşırabilir.')

title('04','Dosyalar nerede, hangisi açılır?')
p('Her koşu için yeni tarih-saat klasörü oluşur. Terminaldeki <b>Saved</b> satırı doğrudan kayıt dosyasını, <b>OUTPUT</b> satırı koşunun ana klasörünü gösterir.')
code('traces/\n  v1/                           # veya v2\n    S5/                         # veya S0\n      <tarih-saat>-observation/\n        session.json\n        dump.json\n        serial_raw.bin\n        window-01/\n          recording.SVDat       # SystemView ile bunu aç\n          trace.json\n          ram.bin\n          openocd.log')
table([['Dosya','Ne için kullanılır?'],['recording.SVDat','İkili SystemView olay kaydı; görev, kesme ve özel işaretler.'],['trace.json','Tek pencerenin tamamlanma, taşma, boyut ve hash bilgisi.'],['session.json','Koşunun senaryosu, derleme bilgisi, kayıt yolları, decoder_errors.'],['dump.json','Uygulamanın t0-t4 ölçümleri ve sayaçları. Kısa izleme pencerelerinin dışındaki olayları da içerebilir.'],['ram.bin / serial_raw.bin','İlki ham SRAM görüntüsü, ikincisi ham uygulama UART verisi. Bu projede doğrudan SystemView kaydı değiller.']], [155,344])
h('Kaydı kullanmadan önce kontrol et')
p('Pencerenin trace.json dosyasında <b>capture_complete: true</b>, <b>clean: true</b> ve <b>dropped_events: 0</b> beklenir. session.json içindeki decoder_errors değerini de kontrol et. “clean” yalnız izleme olay kaybını tarif eder; uygulamanın buton mesajı kaybetmediğini kanıtlamaz.')
p('Dosya oluşmuş olması tek başına yeterli değildir. Betik hata verdiyse kısmi klasörü başarılı deney diye kullanma. Taşma varsa WindowMs değerini azaltıp yeni koşu al.')
small('ram.bin dosyasının uzantısını .SVDat yapmak dönüştürme değildir. Bu projedeki betik ELF sembollerini kullanarak RTT kanal 1 verisini RAM görüntüsünden çıkarır. Ölçüm arşivinde firmware sürümünü, senaryoyu, ELF/build bilgisini ve tüm koşu klasörünü birlikte sakla.')

title('05','SystemView’da dosyayı incele')
h('Dosyayı aç')
p('SystemView’ı başlat. Eğitim kullanımındaki lisans koşullarını kabul ediyorsan <b>Continue under SFL</b>, ardından varsa sistem bilgisi penceresinde <b>OK</b> seç. <b>File → Load Recording</b> (Ctrl+O) ile recording.SVDat dosyasını aç. [1]')
p('İstersen hazır betikle, dosya yolunu açıkça ver:')
code('$trace = ".\\traces\\v1\\S5\\20261004-151332-observation"\n.\\tools\\open-systemview.ps1 `\n  -Trace "$trace\\window-02\\recording.SVDat"')
small('Bu, mevcut arşivdeki V1 S5 örneğini açar. Yeni kaydın için terminalde yazan yolu kullan. open-systemview.ps1 parametresiz çalışırsa yalnız V2 altındaki en yeni temiz kaydı seçer; V1 için -Trace kullan.')
h('Ekranı okuma sırası')
p('<b>Events List:</b> BTN_ACCEPT olayını ve Detail içindeki run/id değerlerini bul. Satıra çift tıklayarak Timeline’ı aynı olaya getir. Listedeki # sıra numarası, uygulamadaki id ile aynı şey değildir.<br/><b>Timeline:</b> görevlerin hangi aralıkta çalıştığını izle.<br/><b>CPU Load:</b> görünen zaman aralığındaki yük dağılımını incele; yakınlaştırma değişince aralık da değişir.')
img=Image(str(ROOT/'reports/evidence/v2-s5-timeline.png'),width=499,height=187)
story.append(img)
small('Kendi V2 S5 ekranın: ButtonTask satırında gri çerçeveli 689,9 µs aralığı Ready beklemesi; turkuaz 54,7 µs aralığı çalışmadır. Yüksek öncelikli TelemetryTask CPU’yu kullanırken buton görevi bekler.')
p('<b>Gri = her zaman Blocked değildir.</b> Ready, görevin çalışabilecek durumda CPU beklemesidir. Blocked, kuyruk, bildirim veya süre gibi bir koşulu beklemesidir. Soluk satır arka planını çalışma çubuğuyla karıştırma; Task Block olayını ve bekleme nedenini de kontrol et.')
small('Task Run/Task Block görünmüyorsa View → Event Filter → Show Tasks filtresini kontrol et. Ctrl+Shift+Space filtreleri sıfırlar. Ctrl+G ile SystemView olay sıra numarasına gidebilirsin. [1]')

title('06','“Neden gecikti?” sorusunu cevapla')
p('Bir buton olayını sürüm + koşu klasörü + run + id ile eşleştir. Sadece id kullanma; kart yeniden başlayınca veya başka koşuda aynı sayı yeniden kullanılabilir.')
table([['İşaret','Ölçüm sınırı'],['BTN_ACCEPT / t0','EXTI içinde kabul edilen buton olayı.'],['BTN_TASK / t1','ButtonTask olayını kuyruktan alır. Task Run ile aynı sınır değildir.'],['BTN_READY / t2','Mesaj hazırlığı tamamlanır.'],['BTN_ENQUEUE','Mesaj TX kuyruğuna konur; doluluğu incele.'],['BTN_TX_START / t3','DMA gönderimini başlatma sınırı.'],['BTN_TX_TC / t4','UART aktarımının tamamlanma callback’i.'],['BTN_DROP','Mesaj düşmüştür; t3 ve t4 yoksa gecikmeyi sıfır yazma.']], [160,339])
h('Dört aşamayı ayrı düşün')
p('<b>t1-t0:</b> kesmeden olayı işleyene kadar bekleme.<br/><b>t2-t1:</b> mesaj hazırlama.<br/><b>t3-t2:</b> TX kuyruğu ve gönderim başlangıcı için bekleme.<br/><b>t4-t3:</b> aktarımın tamamlanması.<br/><b>Toplam:</b> t4-t0. DMA aktarım süresinin tamamını CPU çalışma süresi sayma.')
h('Mevcut arşivle ilk alıştırman')
p('V1 S5, <b>20261004-151332-observation/window-02</b> kaydını aç. Ctrl+G ile <b>#1732</b> olayına git: run=2, id=18 için BTN_ACCEPT. Aynı olay #1738’de BTN_TASK, #1739’da BTN_READY, #2765’te TX başlangıcı, #2799’da TX tamamlanmasıdır.')
p('Bu olayda aşamalar <b>24 + 27 + 156449 + 5562 = 162062 µs</b>. Baskın süre mesaj hazırlığı değil, TX öncesi beklemedir. Kuyruk doluluğu ve TelemetryTask çalışması bunun nedenini incelemeni sağlar. Bunlar yeni kayıtta aynı sıra numaralarında olmak zorunda değildir.')
h('Rapor yazarken')
p('V1 S0 ile V2 S0’ı; V1 S5 ile V2 S5’i karşılaştır. S0’da baud değişimi hat süresini açıklar. S5’te daha hızlı UART, ayrı kuyruklar, BTN önce seçimi ve CPU işinin dilimlenmesi birlikte etkilidir. Mevcut deney bunların her birine ayrı kazanç yüzdesi vermez.')
small('Rapor sayıları uygulamanın TIM5 t0-t4 değerlerinden gelir. SystemView zamanları farklı işaret sınırlarına ve izleme çağrısı zamanına aittir; birebir aynı sonucu bekleme. SWD okuma ve izleme kodunun etkisi sıfır kabul edilmemelidir. Kaynak: reports/V1_V2_Karsilastirma.md.')

title('07','Sürüm değiştir veya kodunu yenile')
p('Yalnız eski kayıtları incelemek için derleme ve yükleme gerekmez. Kod değiştirdiğinde veya V1’den V2’ye geçtiğinde <b>derle → karta yükle → eşleşen betikle kayıt al</b> sırasını uygula.')
h('1. İzleme destekli derle')
code('$py = ".\\projects\\v2\\interface\\.venv\\Scripts\\python.exe"\n\n# V1\n& $py .\\projects\\v1\\firmware\\build.py `\n  --config Release --trace systemview\n\n# V2-QWB\n& $py .\\projects\\v2\\firmware\\build.py `\n  --config Release --variant QWB --trace systemview')
p('Sadece kullanacağın sürümü derle. Başarıyla tamamlandığını kontrol et. Oluşan ELF yolları:')
code('# V1\nprojects/v1/firmware/build/v1/Release/systemview/Homework_001.elf\n\n# V2-QWB\nprojects/v2/firmware/build/v2/QWB/Release/systemview/Homework_001.elf')
h('2. Aynı ELF’i karta yükle')
p('STM32CubeProgrammer’da ST-LINK bağlantısıyla karta bağlan. İlgili ELF dosyasını seçip programla, doğrulamanın başarılı olduğunu kontrol et, kartı resetleyip çalıştır. Kayıt almadan önce programlayıcının ST-LINK bağlantısını kapat. Sonra doğru capture betiğini kullan.')
h('3. Yapılandırmayı koru')
p('Mevcut entegrasyon <b>FreeRTOS 10.3.1</b> ve ona uyarlanmış V10 izleme kancalarını kullanır. Sırf SystemView kullanmak için RTOS sürümünü değiştirmen gerekmez. V1/V2 USART2 hızları sırasıyla 115200 ve 460800’dür; kayıt betikleri bunu kendileri ayarlar.')
p('CubeMX ile .ioc dosyasından yeniden üretim yaparsan elle eklenmiş izleme kancalarını kaybetmediğini diff ile kontrol et. integrate_v1.py, integrate_v2.py ve instrument_app.py günlük kayıt komutları değildir; hazırlanmış projede tekrar çalıştırma.')
small('Derleme çıktıları ve bilgisayardaki .venv GitHub’a eklenmez. Yeni bilgisayarda repo tek başına hazır çalışma ortamı değildir: STM32 araçları, Python ortamı, SystemView ve açıklama dosyaları ayrıca hazırlanır. Kayıt betikleri ST araçlarını C:/ST altında arar.')

title('08','Yeni projende nasıl kullanırsın?')
p('Bu projedeki kayıt araçları STM32F407 ve kendi UART protokolümüz için yazıldı. Aynı MCU ailesinde bile linker düzeni, UART protokolü ve semboller değişirse uyarlama gerekir.')
table([['Katman','Yapılacak iş'],['1. İzleme kaynakları','SystemView + RTT kaynaklarını ve kullandığın FreeRTOS sürümüne uygun adaptörü derlemeye ekle. Kütüphane sürümlerini sabitle.'],['2. RTOS olayları','Görev geçişi, Ready/Blocked ve ilgili RTOS API kancalarını doğru bağla. Aynı olayı iki kez kaydetme.'],['3. Zaman ve bellek','Zaman damgası kaynağını ve frekansını doğrula. RAM tamponunu, heap/stack ihtiyacını ve taşma davranışını bütçele.'],['4. Başlatma','İzleme yapılandırmasını başlat. Görev adları ve modül açıklamalarının her kayıtta mevcut olmasını sağla.'],['5. Uygulama işaretleri','İşin başlangıcı, kuyruğa giriş, işleme ve tamamlanma noktalarını adlandır. Kesme içinde bloklayan iş ekleme.'],['6. Bilgisayara aktarım','Mevcut ST-LINK snapshot yolunu uyarlayabilir veya uygun donanım/firmware ile başka bir recorder seçebilirsin.'],['7. Doğrulama','Önce tek görev ve düşük olay hızında dene. Bilinen bir periyodu doğrula; sonra yükü artırıp olay kaybını kontrol et.']], [128,371])
h('Buradaki özel varsayımları bil')
p('Mevcut betik 0x20000000 adresinden 128 KiB SRAM okur; 32 bit RTT tanımını, kanal 1’i ve uygulamaya özel app_trace_* sembollerini kullanır. Başka kartta bu adresleri ve belleğin büyüklüğünü aynen kopyalama.')
p('Bizde tampon 64 KiB, zaman damgası DWT tabanlı ve CPU 168 MHz’dir. Başka MCU’da DWT bulunmayabilir veya düşük güç durumunda davranışı değişebilir. Uygulama ölçümlerindeki TIM5 kaynağı da ayrıca uyarlanmalıdır.')
p('<b>TRACE komutu, AppTrace yardımcıları ve capture betikleri projeye özeldir.</b> SystemView kullanan her yazılım bu UART komutlarını otomatik olarak anlamaz. Canlı izlemeye geçiş için uygun recorder ve firmware taşıma katmanı gerekir; USB-TTL takmak tek başına yeterli değildir.')
small('Yeni bilgisayarda: tools/SystemView-4.10a içindeki uygulamayı kur; docs/systemview-description içindeki SYSVIEW_*.txt dosyalarını uygulamanın Description klasörüne taşı. Ortak Python ortamını requirements.txt ile hazırla, STM32 toolchain/OpenOCD yollarını doğrula ve kaynaklardan yeniden derle. Bunlar mevcut yerel kurulumda zaten hazırlanmıştır.')

title('09','Takılırsan buradan kontrol et')
